int[] scores = new int[5];
double[] temps = { 20.5, 21.0, 19.8 };
string[] names = new string[] { "A", "B", "C" };

int[] values = { 10, 20, 30, 40 };
Console.WriteLine(values[0]); // 10
Console.WriteLine(values[2]); // 30
values[1] = 25;
Console.WriteLine(values[1]); // 25

int[] numbers = { 5, 10, 15, 20 };
Console.WriteLine(numbers.Length); // 4
for (int i = 0; i < numbers.Length; i++)
{
    Console.WriteLine(numbers[i]);
}

int[] numbers = { 1, 2, 3 };
foreach (int n in numbers)
{
    Console.WriteLine(n * 2);
}

int[] nums = { 3, 1, 4, 1, 5 };
Array.Sort(nums);
Array.Reverse(nums);
Console.WriteLine(nums[0]); // 5
Console.WriteLine(Array.IndexOf(nums, 3)); // -1

int[] data = { 1, 2, 3 };
// Check bounds
if (index >= 0 && index < data.Length)
{
    Console.WriteLine(data[index]);
}
// Prefer foreach for reading
foreach (int value in data)
{
    Console.WriteLine(value);
}

